// CROSS-PACKAGE re-export by BARE specifier -- the facade/wrapper shape.
// The call graph deliberately chases this hop when following a VALUE
// (RWF-004b). Advisory OWNERSHIP is a different question: a crosspkg-lib
// advisory must not be re-interpreted as an outside-lib target, so
// target-side resolution refuses it and the target stays unresolved.
exports.vulnerable = require("outside-lib").vulnerable;
